window.RP_SESSION={"id":"S-414f9204cc14","messages":[{"id":"RP-0266898","time":"2026-09-08T03:39:00+09:00","room":"RP","name":"션","profile":"델타인","identity":"reviewed","type":"dialogue","body":"불은 꺼지지 않는다.","characters":["P-3bbc4a823df9"]},{"id":"RP-0266899","time":"2026-09-08T03:40:00+09:00","room":"RP","name":"션","profile":"델타인","identity":"reviewed","type":"dialogue","body":"흔히들 사람이 죽는 것은 등불이 꺼지는 것과 같다고들 한다.","characters":["P-3bbc4a823df9"]},{"id":"RP-0266900","time":"2026-09-08T03:40:00+09:00","room":"RP","name":"션","profile":"델타인","identity":"reviewed","type":"dialogue","body":"그것은 주로 생명의 불꽃을 다 태웠다는 의미이다.","characters":["P-3bbc4a823df9"]},{"id":"RP-0266901","time":"2026-09-08T03:42:00+09:00","room":"RP","name":"션","profile":"델타인","identity":"reviewed","type":"dialogue","body":"의뢰를 다녀오고, 마리우스와 좀 놀고, 업무를 처리하고, 뒤이어 저녁을 먹기 전. 션은 사이먼의 불꽃이 꺼졌다는 것을 확실히 확인했다.","characters":["P-3bbc4a823df9"]},{"id":"RP-0266902","time":"2026-09-08T03:45:00+09:00","room":"RP","name":"션","profile":"델타인","identity":"reviewed","type":"dialogue","body":"두 개의 큰 전쟁과 잡다한 역병 치레를 거치며 일손 인구 변화와 전염병 동향을 파악하기 위해, 매달 도심에서 누가 죽어나갔는지 체크하는 사망자 명단(Bills of Mortality).","characters":["P-3bbc4a823df9"]},{"id":"RP-0266903","time":"2026-09-08T03:46:00+09:00","room":"RP","name":"션","profile":"델타인","identity":"reviewed","type":"dialogue","body":"그리고 사이먼은 죽기 전까지 사제복을 입고 있었기에… 대성당의 교구 등록부(Parish Registers)에도 짤막한 한 줄이나마 기록은 되어 있었다.","characters":["P-3bbc4a823df9"]},{"id":"RP-0266904","time":"2026-09-08T03:48:00+09:00","room":"RP","name":"션","profile":"델타인","identity":"reviewed","type":"dialogue","body":"대성당에서 맡은 절향이 아직도 코 끝에 맴돈다. 마력초 궐련으로도 지워지지 않는 것 같다.","characters":["P-3bbc4a823df9"]},{"id":"RP-0266905","time":"2026-09-08T03:48:00+09:00","room":"RP","name":"션","profile":"델타인","identity":"reviewed","type":"dialogue","body":"사이먼의 불꽃도 이 절향처럼 제 색을 남겼을까?","characters":["P-3bbc4a823df9"]},{"id":"RP-0266906","time":"2026-09-08T03:49:00+09:00","room":"RP","name":"션","profile":"델타인","identity":"reviewed","type":"dialogue","body":"엘라는? 티아멧은?","characters":["P-3bbc4a823df9"]},{"id":"RP-0266907","time":"2026-09-08T03:51:00+09:00","room":"RP","name":"션","profile":"델타인","identity":"reviewed","type":"dialogue","body":"천천히 숨을 들이쉴 때마다 담배의 끝이 붉게 물들며 타들어갔다.","characters":["P-3bbc4a823df9"]},{"id":"RP-0266908","time":"2026-09-08T03:52:00+09:00","room":"RP","name":"션","profile":"델타인","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-3bbc4a823df9"]},{"id":"RP-0266909","time":"2026-09-08T03:52:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"다음을 기대할게..!","characters":[]}]};
